mapper.delete:

/* deleteGrpAuth - Lee JiSeob */

DELETE FROM SAB300 /* 권한별 메뉴 */
WHERE AUTHRT_ID = #{rightId} 
AND MENU_NO = #{menuId}


/* deleteGrpAuthAll - Kang.hwayoung */

DELETE FROM SAB300 /* 권한별 메뉴 */
WHERE AUTHRT_ID = #{rightId}


/* deleteUnavailGrpAuth - Lee JiSeob */

DELETE FROM SAB300 C /* 권한별 메뉴 */
WHERE NOT EXISTS (
    SELECT D.MENU_NO FROM SAB200 D WHERE D.MENU_NO = C.MENU_NO
)

mapper.update:

/* saveGroupDetailAuths - Lee JiSeob */

UPDATE SAB300 /* 권한별 메뉴 */
SET
    INQ_BUTTON_USE_YN = #{RIGHT_VIEW},
    DTL_INQ_BUTTON_USE_YN = #{RIGHT_DETAIL},
    INITL_BUTTON_USE_YN = #{RIGHT_INIT},
    REG_BUTTON_USE_YN = #{RIGHT_CREATE},
    MDFCN_BUTTON_USE_YN = #{RIGHT_UPDATE},
    DEL_BUTTON_USE_YN = #{RIGHT_DELETE},
    MNG_BUTTON_USE_YN = #{RIGHT_MANAGE}
WHERE
    AUTHRT_ID = #{AUTHRT_ID}
    AND MENU_NO = #{MENU_NO}

mapper.select:

/* selectGrpAuthPersons - Lee JiSeob */

SELECT
    DISTINCT USER_ID

FROM SAB230 /* 사용자별 기관 권한 */

WHERE AUTHRT_SE_CD = #{AUTHRT_SE_CD}

/* selectMenuAuths - Lee JiSeob */
SELECT AUTHRT_ID, MENU_NO,
INQ_BUTTON_USE_YN, INITL_BUTTON_USE_YN, REG_BUTTON_USE_YN, MDFCN_BUTTON_USE_YN, DEL_BUTTON_USE_YN, MNG_BUTTON_USE_YN, DTL_INQ_BUTTON_USE_YN
FROM SAB300 C /* 권한별 메뉴 */
WHERE C.AUTHRT_ID = #{rightId}


/* selectMenuAuthCount - Lee JiSeob */

SELECT
    COUNT(*) AS CNT

FROM SAB250 C /* 사용자별 메뉴권한 */

WHERE C.USER_ID = #{userId}
AND C.MENU_NO = #{menuNo}

mapper.delete:

/* deleteMenuAuths - Lee JiSeob */

DELETE FROM SAB250 C /* 사용자별 메뉴권한 */

WHERE USER_ID = #{USER_ID} 
AND MENU_NO = #{MENU_NO}

